// Original exposition: assumptions, derivations, counterexamples and numerical
// checks are kept together so a formula never loses its conditions of use.
const reading = {
  habr: 'https://habr.com/ru/articles/514818/',
  linear: 'https://education.yandex.ru/handbook/ml/article/linear-models',
  probability: 'https://education.yandex.ru/handbook/ml/article/veroyatnostnyj-podhod-v-ml',
  bayes: 'https://education.yandex.ru/handbook/ml/article/bajesovskij-podhod-k-ocenivaniyu',
  statistics: 'https://www.hse.ru/mirror/pubs/share/508524813.pdf'
};

function note(text) { return `<div class="theory-callout">${text}</div>`; }
function cite(key, label) { return `<p class="theory-reading">Продолжить чтение: <a href="${reading[key]}" target="_blank" rel="noreferrer">${label} ↗</a></p>`; }
function table(headers, rows, caption) {
  return `<div class="math-table-scroll" tabindex="0" role="region" aria-label="${caption}"><table class="math-table"><caption>${caption}</caption><thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map((cell, i) => i ? `<td>${cell}</td>` : `<th scope="row">${cell}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function exampleVisual() {
  const sx = x => 65 + x * 115, sy = y => 285 - y * 43;
  const points = [[1, 2], [2, 3], [3, 5], [4, 4]];
  return `<figure class="theory-visual math-figure"><svg viewBox="0 0 680 330" role="img" aria-labelledby="linear-example-caption"><title>МНК на четырёх наблюдениях</title>
    <path class="theory-grid" d="M65 70H610M65 156H610M65 242H610M180 45V285M295 45V285M410 45V285M525 45V285"/>
    <path class="theory-axis" d="M65 38V285H620"/><path class="theory-curve" d="M${sx(0)} ${sy(1.5)}L${sx(4.6)} ${sy(.8 * 4.6 + 1.5)}"/>
    ${points.map(([x,y]) => `<path class="math-residual" d="M${sx(x)} ${sy(y)}V${sy(.8*x+1.5)}"/><circle class="theory-step" cx="${sx(x)}" cy="${sy(y)}" r="6"/><text x="${sx(x)+10}" y="${sy(y)-12}">(${x}, ${y})</text>`).join('')}
    <circle class="math-centroid" cx="${sx(2.5)}" cy="${sy(3.5)}" r="7"/><text x="365" y="160">средние (2.5, 3.5)</text>
    <text x="72" y="30">балл</text><text x="460" y="316">часы подготовки</text><text x="74" y="80">ŷ = 0.8x + 1.5</text>
    </svg><figcaption id="linear-example-caption">Линия проходит через средние. Пунктир — вертикальные ошибки на наблюдениях; МНК минимизирует сумму их квадратов, а не перпендикулярные расстояния до прямой.</figcaption></figure>`;
}

function noiseVisual() {
  const density = [x => Math.exp(-x*x/2)/Math.sqrt(2*Math.PI), x => Math.exp(-Math.SQRT2*Math.abs(x))/Math.SQRT2, x => 1/(Math.PI*(1+x*x))];
  const curves = density.map((f, i) => `<path class="noise-curve noise-${i}" d="${Array.from({length:161}, (_, j) => {const x=-4+j/20;return `${j?'L':'M'}${(60+(x+4)*70).toFixed(2)} ${(265-f(x)*270).toFixed(2)}`;}).join(' ')}"/>`).join('');
  return `<figure class="theory-visual math-figure"><svg viewBox="0 0 680 325" role="img" aria-labelledby="linear-noise-caption"><title>Плотности нормального шума, Лапласа и Коши</title><path class="theory-grid" d="M60 185H620M60 105H620M200 45V265M340 45V265M480 45V265"/><path class="theory-axis" d="M60 35V265H630"/>${curves}<text x="62" y="25">плотность q(ε)</text><text x="335" y="285">0</text><text x="600" y="285">ε</text><text class="noise-label-0" x="75" y="309">Нормальное</text><text class="noise-label-1" x="275" y="309">Лаплас</text><text class="noise-label-2" x="465" y="309">Коши</text></svg><figcaption id="linear-noise-caption">Нормальное N(0,1) и Лаплас с масштабом 1/√2 имеют дисперсию 1. У Коши с масштабом 1 дисперсии и математического ожидания нет; его хвост убывает как 1/ε². Кривые вычислены по плотностям, а не нарисованы произвольно.</figcaption></figure>`;
}

function regularizationVisual() {
  // Isotropic quadratic loss: exact Euclidean projections onto L2/L1 balls.
  const panel = (offset, kind) => {
    const ox=100, oy=245, s=50;
    const center = kind==='l2' ? [2,2] : [2,.3];
    const touch = kind==='l2' ? [Math.SQRT1_2, Math.SQRT1_2] : [1,0];
    const radius = Math.hypot(center[0]-touch[0], center[1]-touch[1])*s;
    const cx=ox+center[0]*s, cy=oy-center[1]*s;
    return `<g transform="translate(${offset} 0)"><text x="30" y="30">${kind==='l2'?'L2: гладкая граница':'L1: касание в углу'}</text><path class="theory-axis" d="M20 ${oy}H340M${ox} 310V45"/>
      <circle class="math-contour" cx="${cx}" cy="${cy}" r="${radius}"/>
      ${kind==='l2'?`<circle class="math-constraint" cx="${ox}" cy="${oy}" r="${s}"/>`:`<path class="math-constraint" d="M${ox+s} ${oy}L${ox} ${oy-s}L${ox-s} ${oy}L${ox} ${oy+s}Z"/>`}
      <circle class="math-centroid" cx="${cx}" cy="${cy}" r="5"/><circle class="theory-step" cx="${ox+touch[0]*s}" cy="${oy-touch[1]*s}" r="6"/>
      <text x="${cx-38}" y="${cy-15}">свободный минимум</text><text x="305" y="250">w₁</text><text x="103" y="60">w₂</text></g>`;
  };
  return `<figure class="theory-visual regularization-geometry math-figure"><svg viewBox="0 0 740 340" role="img" aria-labelledby="linear-penalty-caption"><title>Точные точки касания ограничений L1 и L2 с линией уровня</title>${panel(0,'l2')}${panel(380,'l1')}</svg><figcaption id="linear-penalty-caption">Частный случай квадратичной ошибки с круговыми линиями уровня. Жёлтая граница — допустимые веса; зелёная точка — минимум без ограничения. На L2 оптимум имеет две ненулевые координаты. На L1 в показанном примере w₂=0. Это иллюстрация; общее обоснование разреженности даёт субградиент ниже.</figcaption></figure>`;
}

export function createLinearTheory({ section, notationTable, derivationStack, equationCard }) {
  const blocks = [];
  const add = (id, label, title, body, group) => blocks.push({ id, label, title, body, group });
  const eq = equationCard;
  const proof = (title, steps) => derivationStack(title, steps.map(([formula, explanation]) => ({formula, explanation})));

  add('linear-intro', 'Три взгляда на регрессию', 'Одна модель. Три разных вопроса.', `
    <p>Как по часам подготовки предсказать балл? Сначала найдём прямую, которая лучше всего приближает уже известные ответы. Затем докажем, почему найденные коэффициенты минимизируют ошибку. Наконец спросим: насколько они изменились бы, если бы мы собрали другую выборку?</p>
    <div class="comparison-strip"><article><b>Математический анализ</b><span>Производные находят минимум. Ковариация объясняет наклон прямой.</span></article><article><b>Линейная алгебра</b><span>МНК — проекция. Ранг определяет единственность весов, спектр — устойчивость.</span></article><article><b>Теория вероятностей</b><span>Шум делает оценки случайными. Предположения определяют их точность и допустимые выводы.</span></article></div>
    <p>Понадобятся производная, скалярное произведение, математическое ожидание и дисперсия. Новые обозначения вводятся рядом с доказательствами. Первые разделы обходятся без матриц; к статистике можно вернуться после экспериментов с весами.</p>
    ${note('<b>Что мы считаем доказательством.</b> У каждого результата есть условия, вычисления и вывод. Формула с обратной матрицей без проверки ранга или доверительный интервал без модели шума — ещё не законченный результат.')}
  `, 'Начало');

  add('linear-notation', 'Обозначения', 'Наблюдения, параметры и случайные величины', `
    ${notationTable([
      ['n, d, p=d+1', 'число наблюдений, исходных признаков и параметров с учётом смещения'],
      ['xᵢ, yᵢ', 'известные значения признака и ответа в одномерном примере'],
      ['a, b', 'наклон и смещение в модели ŷ=ax+b; в некоторых источниках эти буквы переставлены'],
      ['x̄, ȳ', 'средние по наблюдаемой выборке: Σxᵢ/n и Σyᵢ/n'],
      ['X₀ ∈ ℝⁿˣᵈ', 'таблица исходных признаков без столбца единиц'],
      ['X=[1 X₀] ∈ ℝⁿˣᵖ', 'матрица дизайна с первым столбцом из единиц'],
      ['β=(b,w₁,…,w_d)ᵀ', 'общий столбец параметров; β̂ — его оценка по данным'],
      ['y, ŷ ∈ ℝⁿ', 'столбец ответов и столбец прогнозов: ŷ=Xβ'],
      ['e=y−ŷ, r=ŷ−y=−e', 'остатки; оба знака встречаются в литературе, квадрат одинаков'],
      ['ε', 'ненаблюдаемый случайный шум в истинном механизме, не то же самое, что остаток e'],
      ['E, Var, Cov', 'математическое ожидание, дисперсия и ковариация'],
      ['U, Y', 'случайные признак и ответ; букву X далее оставляем для матрицы'],
      ['‖v‖²₂=Σvⱼ²', 'квадрат евклидовой нормы'],
      ['Aᵀ, I, tr(A)', 'транспонирование, единичная матрица и сумма диагональных элементов']
    ])}
    <p>Условная запись E[ε|X]=0 означает: после фиксации <em>всей</em> матрицы признаков средний шум равен нулю. В чисто алгебраической части X и y — просто заданные числа. Статистические предпосылки понадобятся позже.</p>
  `, 'Начало');

  add('linear-model', 'Модель и задача', 'Линейность относится к параметрам', `
    ${eq('ŷᵢ = b + Σ<sub>j=1</sub><sup>d</sup>wⱼxᵢⱼ, &nbsp; ŷ = Xβ', 'Одна строка матрицы X умножается на β и даёт один прогноз.')}
    <p>Коэффициент wⱼ — изменение прогноза на единицу j-го признака при фиксированных остальных. Его единицы — единицы ответа, делённые на единицы признака. Измерить площадь в м² или см² означает получить разные численные веса при том же прогнозе.</p>
    <p>Модель b+w₁x+w₂x² тоже линейная по весам. Нелинейна она по исходному x. А модель exp(wx) уже нелинейна по w. Дальнейший МНК применим к любым заранее выбранным столбцам X, включая полиномиальные признаки.</p>
  `, 'Начало');

  add('linear-objective', 'Что минимизируем', 'Квадратичная ошибка и роль смещения', `
    ${eq('J(β) = (1/n)‖Xβ−y‖²₂ = (1/n)Σᵢ(ŷᵢ−yᵢ)²', 'МНК / OLS — метод наименьших квадратов. SSE=nJ — сумма квадратов ошибок.')}
    <p>Все дальнейшие градиенты соответствуют именно MSE с множителем 1/n. Если взять SSE или J/2, точка минимума не изменится, но градиент и допустимый learning rate изменятся. При добавлении регуляризации её относительный масштаб тоже необходимо пересчитать.</p>
    <p>МНК измеряет ошибки по вертикали, в единицах ответа. Он не симметричен по признакам и таргету. Обучить x по y и перевернуть получившуюся прямую — обычно другое решение. Для существенных ошибок измерения в самих признаках нужна отдельная модель.</p>
  `, 'Начало');

  add('linear-scalar-proof', 'Вывод a и b', 'Находим прямую через частные производные', `
    <p>Пусть n≥2 и не все xᵢ равны. Минимизируем J(a,b)=Σ(axᵢ+b−yᵢ)²/n одновременно по a и b.</p>
    ${proof('От производных до формул', [
      ['∂J/∂b = (2/n)Σᵢ(axᵢ+b−yᵢ) = 0', 'Производная внутреннего выражения по b равна 1.'],
      ['aΣᵢxᵢ + nb − Σᵢyᵢ = 0 ⇒ b̂ = ȳ−âx̄', 'Прямая МНК со свободным членом проходит через точку (x̄,ȳ).'],
      ['∂J/∂a = (2/n)Σᵢxᵢ(axᵢ+b−yᵢ) = 0', 'По цепному правилу появляется множитель xᵢ.'],
      ['âΣᵢxᵢ(xᵢ−x̄) = Σᵢxᵢ(yᵢ−ȳ)', 'Подставляем b̂=ȳ−âx̄ в уравнение по a.'],
      ['Σᵢxᵢ(xᵢ−x̄)=Σᵢ(xᵢ−x̄)², &nbsp; Σᵢxᵢ(yᵢ−ȳ)=Σᵢ(xᵢ−x̄)(yᵢ−ȳ)', 'Добавленные средние исчезают, потому что суммы центрированных значений равны нулю.'],
      ['Sₓₓ=Σᵢ(xᵢ−x̄)², &nbsp; Sₓᵧ=Σᵢ(xᵢ−x̄)(yᵢ−ȳ)', 'Обозначаем два вычисляемых по данным числа.'],
      ['â = Sₓᵧ/Sₓₓ, &nbsp; b̂ = ȳ−âx̄', 'Sₓₓ>0 по условию: деление допустимо.']
    ])}
    ${proof('Почему стационарная точка — единственный минимум', [
      ['∇²J = (2/n) [[Σxᵢ², Σxᵢ], [Σxᵢ, n]]', 'Гессиан — матрица вторых производных по (a,b).'],
      ['(u,v)∇²J(u,v)ᵀ = (2/n)Σᵢ(uxᵢ+v)²', 'Квадратичная форма неотрицательна. При разных xᵢ она равна нулю только при u=v=0.'],
      ['det(∇²J) = (4/n²)(nΣxᵢ²−(Σxᵢ)²) = 4Sₓₓ/n > 0', 'Гессиан положительно определён; функция строго выпуклая. Найденная точка — глобальный единственный минимум.']
    ])}
    ${note('<b>Вырожденный случай.</b> Если xᵢ=c для всех i, то Sₓₓ=0: данные не различают a и b. Любая пара ac+b=ȳ минимизирует ошибку. Если же заранее запретить смещение, получится â=Σxᵢyᵢ/Σxᵢ², а не формула через центрированную ковариацию.')}
  `, 'Матан');

  add('linear-covariance', 'Ковариация и корреляция', 'Наклон — совместное изменение, делённое на разброс', `
    ${eq('Covₙ(x,y)=Sₓᵧ/n, &nbsp; Varₙ(x)=Sₓₓ/n<br>â = Covₙ(x,y)/Varₙ(x) = ρₙ · sᵧ/sₓ', 'sₓ²=Sₓₓ/n, sᵧ²=Σ(yᵢ−ȳ)²/n; корреляция ρₙ определена при sₓ,sᵧ>0. Если в ковариации и дисперсии одновременно взять n−1, отношение не изменится.')}
    <p>Ковариация положительна, когда отклонения x и y от своих средних чаще направлены одинаково. Деление на дисперсию x переводит совместное изменение в изменение y на единицу x. После стандартизации обоих столбцов наклон равен корреляции.</p>
    ${proof('Та же связь для случайных величин', [
      ['R(a,b)=E[(Y−aU−b)²], &nbsp; E[U²],E[Y²]&lt;∞, &nbsp; Var(U)&gt;0', 'Это риск по распределению, а не среднее по конкретным строкам. Раскрыв квадрат, получаем полином по a,b.'],
      ['∂R/∂b=2(aE[U]+b−E[Y])=0 ⇒ b*=E[Y]−a*E[U]', 'Оптимальное смещение снова центрирует модель.'],
      ['R(a,b*(a))=Var(Y)−2aCov(U,Y)+a²Var(U)', 'Подставляем смещение и раскрываем квадрат центрированных величин.'],
      ['∂R/∂a=−2Cov(U,Y)+2aVar(U)=0 ⇒ a*=Cov(U,Y)/Var(U)', 'Вторая производная 2Var(U)>0 доказывает единственность.'],
      ['Y=a₀U+b₀+ε ⇒ a*=a₀+Cov(U,ε)/Var(U)', 'Коэффициент восстанавливает a₀ лишь при отсутствии линейной связи признака с ошибкой. E[ε|U]=0 достаточно для Cov(U,ε)=0.']
    ])}
    <p>Нулевая ковариация не доказывает независимость. Например, для U, равномерного на [−1,1], и Y=U² получаем Cov(U,Y)=E[U³]=0. Лучшая прямая — константа E[Y]=1/3, хотя Y полностью определяется U. Так линейная модель может пропустить сильную нелинейную закономерность.</p>
    ${cite('habr', 'Андрей Хлевнюк — «Основы линейной регрессии»')}
  `, 'Матан');

  add('linear-worked-example', 'Пример на четырёх точках', 'Числа, которые можно проверить вручную', `
    <p>Возьмём искусственные данные: часы подготовки x=(1,2,3,4) и условные баллы y=(2,3,5,4). Это вычислительный пример, а не утверждение о реальной зависимости успеваемости.</p>
    ${table(['x','y','x−x̄','y−ȳ','(x−x̄)(y−ȳ)','ŷ','e=y−ŷ'],[
      ['1','2','−1.5','−1.5','2.25','2.3','−0.3'],['2','3','−0.5','−0.5','0.25','3.1','−0.1'],['3','5','0.5','1.5','0.75','3.9','1.1'],['4','4','1.5','0.5','0.75','4.7','−0.7']
    ],'Полный расчёт одномерного МНК')}
    ${eq('x̄=2.5, &nbsp; ȳ=3.5, &nbsp; Sₓₓ=5, &nbsp; Sₓᵧ=4<br>â=0.8, &nbsp; b̂=1.5, &nbsp; SSE=1.8, &nbsp; MSE=0.45')}
    ${exampleVisual()}
    <p>Проверка оптимальности: Σeᵢ=0 и Σxᵢeᵢ=−0.3−0.2+3.3−2.8=0. Значит, обе частные производные равны нулю. Эти равенства получились благодаря обучению; они сами по себе не доказывают, что ненаблюдаемый шум независим от признаков.</p>
  `, 'Матан');

  add('linear-analytic', 'Матричный дифференциал', 'Normal equations: от дифференциала к весам', `
    <p>Теперь p параметров, X∈ℝⁿˣᵖ и β∈ℝᵖ. При дифференцировании X и y фиксированы. Малое приращение dβ — столбец той же размерности, что β. Для скалярной функции dJ=(∇J)ᵀdβ.</p>
    ${proof('Дифференцируем матричную запись', [
      ['r=Xβ−y, &nbsp; J=rᵀr/n, &nbsp; dr=X dβ', 'Линейность умножения даёт дифференциал остатка без покоординатного разворачивания.'],
      ['dJ = ((dr)ᵀr+rᵀdr)/n = 2rᵀdr/n', 'Оба слагаемых — одно и то же число: скаляр равен своему транспонированию.'],
      ['dJ = (2/n)rᵀX dβ = [(2/n)Xᵀr]ᵀdβ', 'Переставляем только через транспонирование; порядок матриц нельзя менять произвольно.'],
      ['∇J(β)=(2/n)Xᵀ(Xβ−y), &nbsp; ∇²J=(2/n)XᵀX', 'Считываем коэффициент перед dβ и дифференцируем ещё раз.'],
      ['∇J=0 ⇔ XᵀXβ̂=Xᵀy', 'Это нормальные уравнения. «Нормальные» означает ортогональность, а не гауссовский шум.'],
      ['rank(X)=p ⇒ β̂=(XᵀX)⁻¹Xᵀy', 'Обратная существует при линейно независимых столбцах, в частности n≥p.'],
      ['hᵀ∇²Jh=(2/n)‖Xh‖²&gt;0 для h≠0', 'При полном столбцовом ранге получаем строгую выпуклость и единственный глобальный минимум.']
    ])}
    <p>Тот же градиент получается из J=(βᵀXᵀXβ−2yᵀXβ+yᵀy)/n: для постоянной A производная βᵀAβ равна (A+Aᵀ)β. Здесь A=XᵀX симметрична. Формула «2Aβ» без симметрии неверна.</p>
    ${eq('Размерности: XᵀX — p×p; Xᵀy — p×1; β̂ — p×1', 'Свободный член уже включён первым элементом β. Нельзя после этой формулы ещё раз прибавлять отдельный обученный b.')}
    ${cite('linear', 'Яндекс Учебник — линейные модели')}
  `, 'Линейная алгебра');

  add('linear-rank', 'Ранг, QR и SVD', 'Когда веса не единственны', `
    <p>Пусть два столбца X совпадают. Их коэффициенты могут компенсироваться: добавить t к одному и вычесть t из другого можно без изменения прогнозов. В общем случае это направление h из ядра X: Xh=0.</p>
    ${proof('Все решения через компактное SVD', [
      ['X=UᵣΣᵣVᵣᵀ, &nbsp; rank(X)=r, &nbsp; Σᵣ=diag(s₁,…,sᵣ), sⱼ&gt;0', 'Столбцы Uᵣ и Vᵣ ортонормированы. Разложение оставляет только ненулевые сингулярные значения.'],
      ['‖y−Xβ‖²=‖Uᵣᵀy−ΣᵣVᵣᵀβ‖²+‖(I−UᵣUᵣᵀ)y‖²', 'Разлагаем y на компоненту в пространстве столбцов X и ортогональное дополнение. По теореме Пифагора их квадраты норм складываются. Второе слагаемое не зависит от β.'],
      ['ΣᵣVᵣᵀβ=Uᵣᵀy ⇒ Vᵣᵀβ=Σᵣ⁻¹Uᵣᵀy', 'Первое слагаемое можно обнулить. Все диагональные значения Σᵣ положительны, поэтому обращение допустимо.'],
      ['X⁺=VᵣΣᵣ⁻¹Uᵣᵀ, &nbsp; β̂₀=X⁺y', 'Псевдообратная определена и при r&lt;p.'],
      ['β̂=X⁺y+h, &nbsp; h∈ker(X)', 'Все МНК-решения различаются только невидимой для данных компонентой.'],
      ['ŷ=XX⁺y=UᵣUᵣᵀy', 'Вектор прогнозов на train единственен, даже когда коэффициенты не единственны.'],
      ['‖β̂₀+h‖²=‖β̂₀‖²+‖h‖²', 'β̂₀ лежит в пространстве строк X, ортогональном ядру; это решение минимальной нормы.']
    ])}
    <p>При n&lt;p полный столбцовый ранг невозможен. При полном строковом ранге r=n любой y можно интерполировать с нулевой train-ошибкой. Из этого не следует качество на новых данных: x₀ᵀh может быть ненулевым для объекта вне обучающих строк.</p>
    <p>На практике обычно не строят (XᵀX)⁻¹ явно. При полном ранге тонкое QR-разложение X=QR превращает задачу в треугольную систему Rβ̂=Qᵀy. SVD выявляет почти зависимые направления. Для спектрального числа обусловленности κ₂(XᵀX)=κ₂(X)²: нормальные уравнения усиливают численную неустойчивость.</p>
  `, 'Линейная алгебра');

  add('linear-projection', 'Проекция и R²', 'Почему остаток перпендикулярен признакам', `
    ${proof('Геометрическое доказательство МНК', [
      ['P=XX⁺=UᵣUᵣᵀ, &nbsp; Pᵀ=P, &nbsp; P²=P', 'P — ортогональный проектор на пространство столбцов X.'],
      ['ŷ=Py, &nbsp; e=(I−P)y, &nbsp; Xᵀe=0', 'Остаток ортогонален всему пространству допустимых прогнозов.'],
      ['y−Xβ=e+(ŷ−Xβ)', 'Первое слагаемое перпендикулярно второму.'],
      ['‖y−Xβ‖²=‖e‖²+‖ŷ−Xβ‖² ≥ ‖e‖²', 'Теорема Пифагора доказывает глобальный минимум без производных.']
    ])}
    <p>Если в X есть столбец единиц, то 1ᵀe=0, среднее прогнозов равно ȳ и e ортогонален ŷ−ȳ1. При Sᵧᵧ=Σ(yᵢ−ȳ)²&gt;0 получаем:</p>
    ${eq('Sᵧᵧ = ‖y−ȳ1‖² = ‖ŷ−ȳ1‖² + SSE<br>R² = 1−SSE/Sᵧᵧ ∈ [0,1]')}
    <p>Для одного признака â=Sₓᵧ/Sₓₓ, поэтому ‖ŷ−ȳ1‖²=â²Sₓₓ=Sₓᵧ²/Sₓₓ и R²=Sₓᵧ²/(SₓₓSᵧᵧ)=ρₙ². В нашем примере R²=16/25=0.64. Для нескольких признаков это не квадрат корреляции с каким-то одним признаком.</p>
    ${note('Разложение и границы [0,1] относятся к МНК <b>на train со смещением</b>. На validation/test R² может быть отрицательным. Без смещения или при штрафе ортогональное разложение выше не гарантировано. При постоянном y знаменатель равен нулю.')}
  `, 'Линейная алгебра');

  add('linear-gradient-derivation', 'Покоординатный градиент', 'Что вычисляет кнопка «Один шаг»', `
    ${proof('Цепное правило по каждому весу', [
      ['rᵢ=b+Σⱼwⱼxᵢⱼ−yᵢ, &nbsp; J=Σᵢrᵢ²/n', 'Фиксируем знак ошибки: прогноз минус ответ.'],
      ['∂rᵢ/∂wⱼ=xᵢⱼ, &nbsp; ∂rᵢ/∂b=1', 'Меняем только один параметр, всё остальное считаем постоянным.'],
      ['∂(rᵢ²)/∂wⱼ=2rᵢxᵢⱼ', 'Производная внешнего квадрата умножается на производную остатка.'],
      ['∂J/∂wⱼ=(2/n)Σᵢrᵢxᵢⱼ', 'Усредняем вклад всех наблюдений.'],
      ['∂J/∂b=(2/n)Σᵢrᵢ', 'У столбца смещения вместо признака стоят единицы.'],
      ['wⱼ ← wⱼ−η∂J/∂wⱼ, &nbsp; b ← b−η∂J/∂b', 'Все производные в одном шаге вычисляются на одном и том же старом векторе параметров.']
    ])}
    <p>На четырёх точках при a=b=0: ∂J/∂a=−19.5 и ∂J/∂b=−7. При η=0.05 первый шаг даст a=0.975, b=0.35. Это ещё не оптимум (0.8,1.5), хотя оба параметра уже изменились в сторону уменьшения MSE.</p>
  `, 'Оптимизация');

  add('gradient-direction-proof', 'Почему против градиента', 'Локальное направление убывания', `
    ${proof('Тейлор и Коши–Буняковский', [
      ['J(β+hv)=J(β)+h⟨∇J(β),v⟩+o(h), &nbsp; ‖v‖₂=1', 'Первое приближение по Тейлору задаёт производную по направлению.'],
      ['⟨∇J,v⟩ ≥ −‖∇J‖₂‖v‖₂ = −‖∇J‖₂', 'Неравенство Коши–Буняковского ограничивает возможную скорость убывания.'],
      ['v*=−∇J/‖∇J‖₂ при ∇J≠0', 'В этом направлении нижняя граница достигается. При нулевом градиенте все производные первого порядка равны нулю.']
    ])}
    <p>Это утверждение про бесконечно малый шаг в евклидовой норме. Для конечного η нужен контроль кривизны: даже правильное направление с чрезмерным шагом увеличивает loss.</p>
  `, 'Оптимизация');

  add('linear-gradient', 'Доказательство сходимости', 'Learning rate ограничивает спектр', `
    <p>Обозначим H=2XᵀX/n. При полном столбцовом ранге его собственные значения 0&lt;μ₁≤…≤μₚ. Пусть qₜ=βₜ−β̂ — ошибка параметров.</p>
    ${proof('Что происходит с ошибкой на каждом шаге', [
      ['∇J(βₜ)=H(βₜ−β̂), &nbsp; qₜ₊₁=(I−ηH)qₜ', 'Вычитаем нормальные уравнения из текущего градиента.'],
      ['H=V diag(μⱼ)Vᵀ, &nbsp; cₜ=Vᵀqₜ', 'Переходим в ортонормированный базис собственных векторов.'],
      ['cₜ₊₁,ⱼ=(1−ημⱼ)cₜ,ⱼ', 'Каждое направление теперь живёт независимо.'],
      ['|1−ημⱼ|&lt;1 для всех j ⇔ 0&lt;η&lt;2/μₚ', 'Все компоненты затухают; отсюда βₜ→β̂.'],
      ['‖qₜ‖₂ ≤ ρᵗ‖q₀‖₂, &nbsp; ρ=maxⱼ|1−ημⱼ|&lt;1', 'Получаем количественную геометрическую скорость сходимости.']
    ])}
    <p>При η=2/μₚ старшая компонента меняет знак без уменьшения; выше границы растёт, если присутствовала в начальной ошибке. При неполном ранге нулевые направления не меняются: прогнозы сходятся, а компоненту весов в ядре сохраняет инициализация.</p>
    ${eq('J(β−ηg)=J(β)−η‖g‖²+(η²/2)gᵀHg, &nbsp; g=∇J(β)', 'Для квадратичной функции формула Тейлора точна. При 0<η<2/μₚ и g≠0 из gᵀHg≤μₚ‖g‖² следует строгое убывание.')}
    ${note('Практическая остановка — достижение заданной точности, а не точное равенство весов. Малый шаг может означать маленький η. Округлённый до 0.000 градиент может быть ненулевым. При полном ранге J(β)−J(β̂)≤‖∇J(β)‖²/(2μ₁), поэтому один и тот же маленький градиент даёт разные гарантии при разной обусловленности.')}
  `, 'Оптимизация');

  add('linear-conditioning', 'Масштаб и обусловленность', 'Почему похожие признаки замедляют обучение', `
    <p>Число κ=μₚ/μ₁ измеряет вытянутость квадратичной чаши. Для постоянного шага η*=2/(μ₁+μₚ) худший множитель сжатия равен (κ−1)/(κ+1). Если κ огромно, он почти равен 1: тысячи шагов могут мало менять слабое направление.</p>
    <p>После стандартизации столбцы получают сравнимые масштабы, но почти линейная зависимость не исчезает. Если общая и жилая площади почти дублируют друг друга, веса могут меняться в противоположных направлениях при почти постоянном прогнозе. Это объясняет отличие «прогноз уже стабилен» от «коэффициенты точно определены».</p>
    <p>Средние и масштабы оценивают только на train. Для zⱼ=(xⱼ−mⱼ)/sⱼ и модели b_z+Σw_z,ⱼzⱼ возвращение к исходным единицам даёт w_x,ⱼ=w_z,ⱼ/sⱼ и b_x=b_z−Σw_z,ⱼmⱼ/sⱼ. Постоянный признак с sⱼ=0 нельзя делить на стандартное отклонение.</p>
  `, 'Оптимизация');

  add('gradient-variants', 'Batch и SGD', 'Число шагов и число просмотренных объектов', `
    ${eq('gₜ=(1/m)Σ<sub>i∈Bₜ</sub>∇ℓᵢ(βₜ), &nbsp; βₜ₊₁=βₜ−ηₜgₜ')}
    <p>Full batch использует все n строк, SGD — одну, mini-batch — m строк. Если каждый индекс выбирается равномерно независимо от прошлых шагов, условное ожидание gₜ равно полному градиенту. За одну эпоху просматривают n объектов; шаг — одно обновление. Поэтому 100 шагов разных алгоритмов не означают одинаковый объём работы.</p>
    <p>При постоянном η шум SGD обычно не позволяет весам буквально остановиться. Для сходимости к точному минимуму нужны дополнительные условия; типичные условия на шаги — Σηₜ=∞ и Σηₜ²&lt;∞ вместе с контролем дисперсии стохастических градиентов и устойчивостью итераций. В интерактивном модуле используется полный градиент, поэтому движение детерминировано при фиксированных данных и параметрах.</p>
  `, 'Оптимизация');

  add('linear-probability', 'Условное среднее', 'Случайный шум не обязан быть нормальным', `
    <p>Пусть Y=m(U)+ε, где m(u)=E[Y|U=u], а E[Y²]&lt;∞. Тогда E[ε|U]=0 по определению. Признаки могут быть случайными; при обучении мы наблюдаем одну их реализацию.</p>
    ${proof('Почему MSE ищет именно условное среднее', [
      ['Y−g(U) = ε + m(U)−g(U)', 'Добавляем и вычитаем условное среднее для любой функции прогноза g с конечным риском.'],
      ['E[(Y−g(U))²|U] = E[ε²|U]+(m(U)−g(U))²+2(m(U)−g(U))E[ε|U]', 'При фиксированном U функция m(U)−g(U) — константа.'],
      ['E[(Y−g(U))²|U] = Var(Y|U)+(m(U)−g(U))²', 'Перекрёстное слагаемое равно нулю.'],
      ['argmin<sub>g</sub>E[(Y−g(U))²] = m(U) почти наверное', 'Остаётся минимизировать неотрицательный квадрат; нормальность нигде не использовалась.']
    ])}
    <p>Если ограничиться прямыми, найдём лучшую линейную аппроксимацию m(U). Она совпадёт с m(U) только когда условное среднее линейно. Даже идеально сошедшийся градиентный спуск не исправляет ошибочный класс функций.</p>
    ${note('<b>Среднее шума и распределение — разные предположения.</b> E[ε|X]=0 достаточно для несмещённости МНК при полном ранге. Постоянная дисперсия и некоррелированность нужны для классической формулы дисперсии. Нормальность добавляет точные распределения оценок и статистик на конечной выборке.')}
  `, 'Вероятность и статистика');

  add('linear-loss-derivation', 'Нормальный шум → MSE', 'Вывод максимального правдоподобия', `
    <p>Предположим совместно, условно на X: ε∼N(0,σ²I), σ²&gt;0. Это означает независимые нормальные ошибки с одной дисперсией. Признаки и сами ответы в совокупности нормальными быть не обязаны.</p>
    ${proof('От плотности к оптимизации', [
      ['p(y|X,β,σ²)=(2πσ²)<sup>−n/2</sup> exp(−‖y−Xβ‖²/(2σ²))', 'Совместная плотность — произведение n условных нормальных плотностей. Это плотность, а не вероятность отдельного точного значения y.'],
      ['−log p = (n/2)log(2πσ²)+SSE(β)/(2σ²)', 'Логарифм переводит произведение в сумму.'],
      ['argmin<sub>β</sub>(−log p)=argmin<sub>β</sub>SSE(β)=β̂<sub>OLS</sub>', 'При фиксированной положительной дисперсии добавки и множитель не влияют на оптимальные веса.'],
      ['∂(−log p)/∂v=n/(2v)−SSE/(2v²)=0, &nbsp; v=σ²', 'Если дисперсия неизвестна, её тоже можно оценить.'],
      ['σ̂²<sub>MLE</sub>=SSE(β̂)/n', 'При SSE>0 это оптимум по v>0. Несмещённая оценка будет другой: SSE/(n−p).']
    ])}
    <p>Если SSE=0, правдоподобие неограниченно растёт при σ²→0: конечной совместной MLE с положительной дисперсией нет. В частности, этот случай возможен при интерполяции. ЦПТ иногда мотивирует приближённую нормальность суммы многих малых влияний, но не доказывает её для любого шума.</p>
    ${cite('probability', 'Яндекс Учебник — вероятностный подход в ML')}
  `, 'Вероятность и статистика');

  add('linear-noise-laws', 'Другие распределения шума', 'Выбор плотности меняет функцию потерь', `
    <p>Для независимых ошибок с известной общей плотностью q и фиксированными её параметрами масштаба условное отрицательное лог-правдоподобие равно Σᵢ−log q(eᵢ), где eᵢ=yᵢ−xᵢᵀβ. Отсюда можно вывести loss для конкретной гипотезы о шуме.</p>
    ${table(['Шум','Плотность / поддержка','−log q(e) с точностью до константы','Следствие'],[
      ['Нормальный','q(e)∝exp(−e²/(2σ²))','e²/(2σ²)','МНК; квадратичный рост штрафа.'],
      ['Лаплас, масштаб c>0','q(e)=exp(−|e|/c)/(2c)','|e|/c','MAE; в точечной задаче оптимальна условная медиана.'],
      ['Стьюдент, ν>0, масштаб s>0','q(e)∝(1+e²/(νs²))<sup>−(ν+1)/2</sup>','((ν+1)/2)log(1+e²/(νs²))','Более медленный рост в хвостах; оптимизация в общем случае невыпуклая.'],
      ['Коши, масштаб c>0','q(e)=1/[πc(1+(e/c)²)]','log(1+(e/c)²)','Случай ν=1; нет среднего и дисперсии, обычные аргументы про MSE-риск неприменимы.'],
      ['Равномерный на [−c,c]','q(e)=1/(2c) при |e|≤c, иначе 0','Константа внутри, +∞ снаружи','При известном c любые допустимые веса одинаково правдоподобны.']
    ],'Связь распределения шума с обучением')}
    ${noiseVisual()}
    <p>У Лапласа конечная дисперсия 2c². Поэтому МНК при нулевом условном среднем всё ещё несмещён, хотя уже не совпадает с MLE. У Стьюдента среднее существует при ν&gt;1, дисперсия — при ν&gt;2. Симметрия плотности сама по себе не гарантирует существование математического ожидания.</p>
    <p>Если у равномерного шума неизвестен масштаб, его MLE при фиксированных весах равен maxᵢ|eᵢ|. Подстановка даёт минимизацию максимального абсолютного остатка, а не суммы квадратов. При точной интерполяции снова возникает вырождение масштаба к нулю.</p>
    <p>Асимметричный шум с конечным средним можно центрировать, но центр расположения, медиана и среднее вообще различны. Например, ε=Z−1 для Z∼Exp(1) имеет среднее 0, но медиану log 2−1. MSE и MAE тогда решают разные задачи даже при бесконечном числе данных.</p>
    ${note('Распределение шума описывает отклонения ответов при фиксированных признаках. Гистограмма самого таргета этого не показывает. А нормальность обученных остатков нельзя автоматически приравнять к независимости истинных ошибок.')}
  `, 'Вероятность и статистика');

  add('linear-estimator', 'Несмещённость и дисперсия', 'Насколько случайны найденные коэффициенты', `
    <p>Предположим y=Xβ₀+ε, rank(X)=p, E[ε|X]=0 и конечную Ω=Cov(ε|X). Положим A=(XᵀX)⁻¹Xᵀ, поэтому AX=I.</p>
    ${proof('Два свойства линейной оценки', [
      ['β̂=Ay=AXβ₀+Aε=β₀+Aε', 'Вся случайность весов выражена через линейное преобразование шума.'],
      ['E[β̂|X]=β₀+A E[ε|X]=β₀', 'Это условная несмещённость. При существовании безусловного ожидания она даёт и E[β̂]=β₀.'],
      ['Cov(β̂|X)=AΩAᵀ', 'Для постоянной при фиксированном X матрицы A ковариация преобразуется слева и справа.'],
      ['Ω=σ²I ⇒ Cov(β̂|X)=σ²(XᵀX)⁻¹', 'Используем AAᵀ=(XᵀX)⁻¹. Нормальность не требовалась.']
    ])}
    ${eq('Var(â|x)=σ²/Sₓₓ<br>Var(b̂|x)=σ²(1/n+x̄²/Sₓₓ)<br>Cov(â,b̂|x)=−σ²x̄/Sₓₓ', 'Одномерный случай: â−a₀=Σ(xᵢ−x̄)εᵢ/Sₓₓ, b̂−b₀=ε̄−x̄(â−a₀). Из Σ(xᵢ−x̄)=0 следует Cov(ε̄,â)=0; подстановка даёт все три формулы.')}
    <p>Больший разброс x помогает оценить наклон точнее при том же шуме. Малое Sₓₓ делает оценку неустойчивой. «Несмещённая» означает правильную в среднем по повторным выборкам, а не точную в каждом конкретном наборе.</p>
  `, 'Вероятность и статистика');

  add('linear-gauss-markov', 'Теорема Гаусса–Маркова', 'В каком смысле МНК оптимален', `
    <p>При полном ранге, E[ε|X]=0 и Cov(ε|X)=σ²I МНК имеет наименьшую условную дисперсию среди всех оценок, <em>линейных по y</em> и несмещённых для любого β₀. Это свойство BLUE. Нормальность не нужна.</p>
    ${proof('Доказательство через произвольного конкурента', [
      ['β̃=Cy, &nbsp; E[β̃|X]=CXβ₀', 'C может зависеть от X, но не от ответов y.'],
      ['E[β̃|X]=β₀ для любого β₀ ⇔ CX=I', 'Несмещённость накладывает матричное ограничение.'],
      ['C=A+D, &nbsp; A=(XᵀX)⁻¹Xᵀ ⇒ DX=0', 'Отделяем МНК-часть от произвольного отличия.'],
      ['ADᵀ=(XᵀX)⁻¹XᵀDᵀ=(XᵀX)⁻¹(DX)ᵀ=0', 'Перекрёстные члены ковариации исчезают.'],
      ['Cov(β̃|X)−Cov(β̂|X)=σ²DDᵀ', 'Раскрываем σ²(A+D)(A+D)ᵀ.'],
      ['vᵀ[Cov(β̃|X)−Cov(β̂|X)]v=σ²‖Dᵀv‖²≥0', 'Ни одна линейная комбинация коэффициентов не оценивается конкурентом с меньшей дисперсией.']
    ])}
    <p>Теорема не утверждает оптимальность среди всех возможных процедур и не запрещает ridge иметь меньшую среднеквадратичную ошибку: ridge допускает смещение. При гетероскедастичности предпосылка σ²I нарушается и этот вывод уже не следует.</p>
    ${cite('statistics', 'О. А. Демидова, НИУ ВШЭ — классическая линейная регрессия')}
  `, 'Вероятность и статистика');

  add('linear-inference', 'Дисперсия и интервалы', 'От остатков к статистической неопределённости', `
    <p>Пусть n&gt;p и выполнены условия предыдущего раздела. Остаток e=(I−P)ε; матрица M=I−P симметрична, идемпотентна и имеет ранг n−p.</p>
    ${proof('Почему делим на n−p', [
      ['SSE=eᵀe=εᵀMε', 'Используем M²=M и MX=0.'],
      ['E[εᵀMε|X]=ΣᵢΣⱼMᵢⱼE[εᵢεⱼ|X]=σ²tr(M)', 'При нулевом среднем и Ω=σ²I остаются диагональные слагаемые.'],
      ['tr(M)=n−p ⇒ E[SSE|X]=(n−p)σ²', 'У P ровно p собственных значений 1; у M=I−P единиц уже n−p, остальные значения равны 0.'],
      ['s²=SSE/(n−p) ⇒ E[s²|X]=σ²', 'p оценённых параметров использовали p степеней свободы. MSE=SSE/n смещена вниз как оценка σ².']
    ])}
    <p>Добавим нормальность ε|X∼N(0,σ²I). Тогда β̂|X∼N(β₀,σ²(XᵀX)⁻¹). После ортогонального поворота SSE/σ² — сумма квадратов n−p независимых стандартных нормальных величин, то есть χ² с n−p степенями свободы.</p>
    ${proof('От нормального числителя к t-статистике', [
      ['Cov(Aε,Mε|X)=σ²AM=0', 'AM=0. Совместно нормальные векторы с нулевой ковариацией независимы, поэтому β̂ независимо от s².'],
      ['Zⱼ=(β̂ⱼ−β₀,ⱼ)/(σ√{[(XᵀX)⁻¹]ⱼⱼ}) ∼ N(0,1)', 'Стандартизуем одну координату.'],
      ['Tⱼ=Zⱼ/√[(SSE/σ²)/(n−p)] ∼ t<sub>n−p</sub>', 'Независимое отношение нормальной величины к корню из нормированной χ² имеет распределение Стьюдента.'],
      ['β̂ⱼ ± t<sub>1−α/2,n−p</sub> · s√{[(XᵀX)⁻¹]ⱼⱼ}', 'Инверсия |Tⱼ|≤квантиль даёт доверительный интервал уровня 1−α.']
    ])}
    <p>95% относится к доле интервалов, покрывающих фиксированный истинный параметр в повторных выборках, а не к вероятности фиксированного параметра в уже вычисленном частотном интервале. Проверка H₀:βⱼ=c использует |(β̂ⱼ−c)/SEⱼ| и ту же t-квантиль. Статистическая значимость не означает большой эффект или причинность.</p>
    <p>Без нормального шума эти t-интервалы в общем случае не точны на малой выборке. Асимптотические интервалы требуют условий ЦПТ и подходящей оценки ковариации. При n≤p формула s² с n−p неприменима.</p>
  `, 'Вероятность и статистика');

  add('linear-prediction', 'Среднее и новый ответ', 'Почему предиктивный интервал шире', `
    <p>Пусть x₀ — новый столбец из p признаков, включая единицу, μ₀=x₀ᵀβ₀ и μ̂₀=x₀ᵀβ̂. При той же нормальной модели и независимом новом шуме ε₀ дисперсии равны:</p>
    ${eq('Var(μ̂₀−μ₀|X,x₀)=σ²h₀, &nbsp; h₀=x₀ᵀ(XᵀX)⁻¹x₀<br>Var(Y₀−μ̂₀|X,x₀)=σ²(1+h₀)', 'Y₀=μ₀+ε₀: добавляется дисперсия нового независимого шума σ².')}
    ${eq('Интервал среднего: μ̂₀ ± t<sub>1−α/2,n−p</sub>s√h₀<br>Предиктивный интервал: μ̂₀ ± t<sub>1−α/2,n−p</sub>s√(1+h₀)')}
    <p>В одномерном случае h₀=1/n+(x₀−x̄)²/Sₓₓ. В примере из четырёх точек s²=1.8/2=0.9. При x₀=2.5 получаем h₀=0.25 и μ̂₀=3.5. С t₀.₉₇₅,₂≈4.303 интервал среднего примерно [1.46,5.54], а нового ответа — [−1.06,8.06]. Четыре точки дают мало точности.</p>
    <p>Дальше от x̄ оба интервала шире. Но они описывают неопределённость <em>внутри принятой модели</em>. Если за пределами train зависимость меняется, даже широкий гауссовский интервал может оказаться самоуверенным. Отрицательная нижняя граница для неотрицательного ответа может сигнализировать о неуместной модели, а не о необходимости молча обрезать интервал.</p>
  `, 'Вероятность и статистика');

  add('linear-heteroskedasticity', 'Неодинаковый и зависимый шум', 'Взвешивание и корректные стандартные ошибки', `
    <p>При Ω≠σ²I оценка β̂ остаётся несмещённой, если E[ε|X]=0. Но классическая ковариация неверна: нужна (XᵀX)⁻¹XᵀΩX(XᵀX)⁻¹. Ω может иметь разные дисперсии на диагонали и ненулевые ковариации между строками.</p>
    ${proof('Обобщённый МНК при известной Ω≻0', [
      ['Q(β)=(y−Xβ)ᵀΩ⁻¹(y−Xβ)', 'Штрафуем остатки с учётом их масштаба и зависимости.'],
      ['dQ=−2(y−Xβ)ᵀΩ⁻¹X dβ', 'Ω⁻¹ симметрична и не зависит от β.'],
      ['β̂<sub>GLS</sub>=(XᵀΩ⁻¹X)⁻¹XᵀΩ⁻¹y', 'При полном столбцовом ранге XᵀΩ⁻¹X положительно определена.'],
      ['X*=Ω⁻¹ᐟ²X, &nbsp; y*=Ω⁻¹ᐟ²y, &nbsp; Cov(ε*|X)=I', 'После «отбеливания» это обычный МНК; применяем теорему Гаусса–Маркова.'],
      ['Cov(β̂<sub>GLS</sub>|X)=(XᵀΩ⁻¹X)⁻¹', 'Линейное преобразование шума даёт ковариацию оценки.']
    ])}
    <p>Если Ω=diag(σᵢ²), получаем взвешенный МНК: Σeᵢ²/σᵢ². Менее шумное наблюдение получает больший вес. Формулы остаются теми же, если Ω известна с точностью до общего положительного множителя.</p>
    ${eq('V̂<sub>HC0</sub>=(XᵀX)⁻¹Xᵀ diag(eᵢ²) X(XᵀX)⁻¹', 'Робастная к гетероскедастичности оценка ковариации: меняет стандартные ошибки, но не веса МНК.')}
    <p>HC0 — асимптотическая оценка, не точная гарантия для любых четырёх строк. Ей нужны независимые наблюдения, подходящие моменты и отсутствие доминирующих точек при росте n. Для временной зависимости нужны HAC-оценки, для групповой — кластерные. Подставлять eᵢ² в HC0 при зависимых строках недостаточно.</p>
  `, 'Вероятность и статистика');

  add('linear-consistency', 'Состоятельность и смещение', 'Чего не исправит большая выборка', `
    ${proof('Когда МНК приближается к истинным весам', [
      ['β̂−β₀=(XᵀX/n)⁻¹(Xᵀε/n)', 'Переписываем ошибку оценки в виде двух средних по наблюдениям.'],
      ['XᵀX/n → Q≻0, &nbsp; Xᵀε/n → 0 по вероятности', 'Это достаточные условия: например, i.i.d. строки, конечные вторые моменты и E[xᵢεᵢ]=0 с невырожденным E[xᵢxᵢᵀ].'],
      ['β̂ → β₀ по вероятности', 'Обращение непрерывно около невырожденной Q; произведение сходится к нулю.']
    ])}
    <p>Несмещённость — свойство среднего на конечной выборке; состоятельность — предел при n→∞. Они не заменяют друг друга. При E[xε]≠0 предел будет β₀+Q⁻¹E[xε]: больше данных делает неверный коэффициент всё точнее.</p>
    ${eq('Y=a₀U+γZ+b₀+ε, &nbsp; Cov(U,ε)=0<br>Если Z пропустить: a*=a₀+γCov(U,Z)/Var(U)', 'Один коррелированный пропущенный фактор достаточно меняет наклон. Это точный вывод из ковариационной формулы.')}
    <p>Ошибка измерения признака тоже важна: если наблюдаем W=U+δ, где δ имеет нулевое среднее и независима от U и ε, то регрессия Y=a₀U+b₀+ε на W имеет наклон a₀Var(U)/(Var(U)+Var(δ)). Он сжат к нулю. Обычная регуляризация и дополнительные итерации это смещение не устраняют.</p>
  `, 'Вероятность и статистика');

  add('linear-regularization', 'Ridge: точная формула', 'Добавляем штраф, сохраняя свободный член', `
    <p>В модуле регуляризуются веса признаков, а смещение b — нет. Для общей β=(b,wᵀ)ᵀ введём D=diag(0,1,…,1).</p>
    ${proof('Матричный вывод ridge', [
      ['Jλ(β)=‖Xβ−y‖²/n+λβᵀDβ, &nbsp; λ≥0', 'Это MSE плюс λΣwⱼ².'],
      ['∇Jλ=(2/n)Xᵀ(Xβ−y)+2λDβ', 'Штраф добавляет производную только по весам.'],
      ['(XᵀX+nλD)β̂λ=Xᵀy', 'Множитель n возникает из выбранного усреднения MSE.'],
      ['β̂λ=(XᵀX+nλD)⁻¹Xᵀy при λ>0', 'hᵀ(XᵀX+nλD)h=‖Xh‖²+nλΣhⱼ²: ноль вынуждает все веса h быть нулём, затем столбец единиц вынуждает нулевое смещение. Для непустой выборки матрица обратима.']
    ])}
    <p>После центрирования X_c=X₀−1x̄ᵀ и y_c=y−ȳ1 можно решить ŵλ=(X_cᵀX_c+nλI)⁻¹X_cᵀy_c, затем b̂λ=ȳ−x̄ᵀŵλ. Так видно, почему штраф не тянет средний прогноз к нулю.</p>
  `, 'Регуляризация и практика');

  add('linear-regularization-deep', 'Bias–variance весов', 'За устойчивость платим смещением', `
    <p>Рассмотрим центрированную задачу для весов, A=X_cᵀX_c, k=nλ&gt;0. Условно на дизайн предполагаем E[ε]=0, Cov(ε)=σ²I до центрирования; в произведении X_cᵀε центрирование шума ничего не меняет.</p>
    ${eq('E[ŵλ|X]−w₀=−k(A+kI)⁻¹w₀<br>Cov(ŵλ|X)=σ²(A+kI)⁻¹A(A+kI)⁻¹')}
    <p>Первая формула получается из E[ŵλ]=(A+kI)⁻¹Aw₀ и равенства A=(A+kI)−kI. Вторая — из правила Cov(Bε)=B Cov(ε) Bᵀ.</p>
    ${eq('В направлении с собственным значением dⱼ&gt;0:<br>biasⱼ=−kθⱼ/(dⱼ+k), &nbsp; varianceⱼ=σ²dⱼ/(dⱼ+k)²<br>MSEⱼ=(k²θⱼ²+σ²dⱼ)/(dⱼ+k)²', 'θⱼ — истинный коэффициент в этом собственном направлении. У МНК varianceⱼ=σ²/dⱼ и biasⱼ=0.')}
    <p>При dⱼ≈0 дисперсия МНК огромна, а ridge её уменьшает. При большом истинном θⱼ слишком сильный штраф даёт заметный bias. Поэтому универсального λ для всех задач нет. В сингулярном направлении dⱼ=0 данных для оценки θⱼ нет: ridge выбирает ноль, а не «восстанавливает истину».</p>
    <p>При SVD X_c=UΣVᵀ весовой множитель меняется с 1/sⱼ у МНК на sⱼ/(sⱼ²+nλ) у ridge. Это делает наглядной связь между регуляризацией, шумом и маленькими сингулярными значениями.</p>
  `, 'Регуляризация и практика');

  add('linear-lasso-geometry', 'L1 и L2', 'Почему L1 может дать ровно нулевой вес', `
    ${regularizationVisual()}
    ${proof('Условие оптимума Lasso', [
      ['min<sub>w</sub> J(w)+λΣⱼ|wⱼ|', 'В центрированной задаче свободный член восстанавливается отдельно.'],
      ['∂|wⱼ|={sign(wⱼ)} при wⱼ≠0; &nbsp; ∂|0|=[−1,1]', 'В нуле модуль имеет целый интервал субградиентов.'],
      ['0∈∂ⱼJ+λ∂|wⱼ|', 'Для выпуклой функции это необходимое и достаточное условие оптимума по координате при остальных зафиксированных.'],
      ['wⱼ=0 допустим в оптимуме ⇔ |∂ⱼJ|≤λ', 'L1 может уравновесить ненулевой градиент ошибки прямо в нуле. У гладкого L2 такого интервала нет.']
    ])}
    <p>Если X_cᵀX_c/n=I и c=X_cᵀy_c/n, то J(w)=Σⱼ(wⱼ−cⱼ)²+const. Условие выше даёт ŵⱼ=sign(cⱼ)max(|cⱼ|−λ/2,0). Порог именно λ/2 из-за MSE без множителя 1/2. При коррелированных столбцах покоординатной независимости уже нет.</p>
    ${proof('Вывод мягкого порога для одной координаты', [
      ['wⱼ&gt;0: 2(wⱼ−cⱼ)+λ=0 ⇒ wⱼ=cⱼ−λ/2', 'Эта ветвь согласована со знаком wⱼ только при cⱼ>λ/2.'],
      ['wⱼ&lt;0: 2(wⱼ−cⱼ)−λ=0 ⇒ wⱼ=cⱼ+λ/2', 'Отрицательная ветвь требует cⱼ<−λ/2.'],
      ['wⱼ=0: 0∈−2cⱼ+λ[−1,1] ⇔ |cⱼ|≤λ/2', 'Когда ни одна ненулевая ветвь не допустима, интервал субградиентов содержит ноль. Это три случая одной формулы soft-thresholding.']
    ])}
    <p>L1 часто выбирает один из коррелированных признаков, но это не доказывает его причинную важность. Штрафы зависят от единиц измерения; масштабирование перед ridge/lasso должно быть осмысленным.</p>
  `, 'Регуляризация и практика');

  add('linear-bayes', 'Байесовский взгляд', 'MAP и распределение весов после данных', `
    <p>Рассмотрим модель y|β,X∼N(Xβ,σ²I) с известной σ² и собственным нормальным prior β∼N(m₀,V₀), V₀≻0. Prior описывает неопределённость параметров до выборки.</p>
    ${proof('Дополняем квадрат в апостериорной плотности', [
      ['−2log p(β|X,y)=‖y−Xβ‖²/σ²+(β−m₀)ᵀV₀⁻¹(β−m₀)+const', 'Формула Байеса: posterior пропорционален likelihood × prior.'],
      ['Vₙ⁻¹=XᵀX/σ²+V₀⁻¹, &nbsp; h=Xᵀy/σ²+V₀⁻¹m₀', 'После раскрытия скобок квадратичная часть равна βᵀVₙ⁻¹β−2βᵀh.'],
      ['mₙ=Vₙh ⇒ βᵀVₙ⁻¹β−2βᵀh=(β−mₙ)ᵀVₙ⁻¹(β−mₙ)+const', 'Дополнение квадрата показывает и центр, и кривизну плотности.'],
      ['β|X,y∼N(mₙ,Vₙ), &nbsp; β̂<sub>MAP</sub>=E[β|X,y]=mₙ', 'Для этой нормальной модели мода совпадает со средним; в общем случае это неверно.'],
      ['Y₀|x₀,X,y∼N(x₀ᵀmₙ, σ²+x₀ᵀVₙx₀)', 'Интегрируем неопределённость весов и добавляем независимый шум нового ответа.']
    ])}
    ${eq('Prior w∼N(0,τ²I) ⇒ λ<sub>MSE</sub>=σ²/(nτ²)', 'Умножаем отрицательное log-posterior на 2σ²/n. Для loss=SSE вместо MSE коэффициент штрафа был бы σ²/τ².')}
    <p>Чтобы получить ridge из модуля без штрафа на b, используем нормальный prior только на w и плоский prior на b. Плоская плотность на всей прямой не нормируется, поэтому это несобственный prior, а не подстановка в V₀≻0. Для непустой выборки posterior остаётся собственным благодаря столбцу единиц и штрафу на все веса.</p>
    <p>Лапласовский prior на w даёт L1-штраф. Не путай его с лапласовским <em>шумом</em>: первый меняет регуляризацию, второй — loss на данных. Байесовский интервал имеет вероятностный смысл относительно posterior; его корректность зависит в том числе от prior и модели данных.</p>
    ${cite('bayes', 'Яндекс Учебник — байесовский подход к оцениванию')}
  `, 'Регуляризация и практика');

  add('linear-bias-variance', 'Разложение ошибки прогноза', 'Доказательство bias² + variance + noise', `
    <p>Зафиксируем новый x. Пусть f(x)=E[Y|x], σ²(x)=Var(Y|x), обучающая выборка D независима от нового ответа, а все следующие вторые моменты конечны. Обозначим m=E_D[f̂_D(x)].</p>
    ${proof('Раскрываем квадрат и проверяем смешанные члены', [
      ['f̂_D(x)−Y = (f̂_D(x)−m)+(m−f(x))−ε', 'Три слагаемых: разброс обученной модели, систематическое отклонение и шум нового ответа.'],
      ['E_D[f̂_D−m]=0, &nbsp; E[ε|x]=0', 'Средние двух случайных слагаемых равны нулю.'],
      ['E[(f̂_D−m)ε|x]=0', 'Новый шум независим от обучения и имеет нулевое условное среднее. Остальные смешанные члены тоже обнуляются.'],
      ['E<sub>D,Y|x</sub>[(f̂_D(x)−Y)²]=(m−f(x))²+Var_D(f̂_D(x))+σ²(x)', 'Остаются ровно три квадратичных вклада.']
    ])}
    <p>Это точное равенство при заданных условиях. Слагаемое noise нельзя уменьшить настройкой весов при фиксированном наборе информации. Можно изменить саму постановку: измерить дополнительные полезные признаки или улучшить качество измерений. Регуляризация действует на первые два слагаемых, а не удаляет шум из мира.</p>
  `, 'Регуляризация и практика');

  add('linear-feature-map', 'Нелинейность и новые признаки', 'Когда прямая — слишком узкая гипотеза', `
    <p>В примере Y=U² прямая не находит зависимость из-за нулевой ковариации. Добавим φ(U)=(U,U²) — и модель b+w₁U+w₂U² включает правильную функцию. Матрица X меняется, но доказательства МНК сохраняются: параметры всё ещё входят линейно.</p>
    <p>Полиномы высокого порядка часто имеют почти зависимые столбцы и легко переобучаются. Степень, преобразования и λ выбирают на validation. Категориальные признаки кодируют индикаторами; вместе со свободным членом полный one-hot для одной категории даёт точную зависимость столбцов, поэтому обычно убирают одну базовую категорию.</p>
    <p>Нельзя из низкого train-MSE заключить, что получилась адекватная модель. При расширении пространства признаков МНК может только уменьшить train-SSE: старое решение остаётся допустимым с нулевыми новыми весами. Это алгебраическое свойство, а не доказательство обобщения.</p>
  `, 'Регуляризация и практика');

  add('linear-loss-catalog', 'Другие loss и метрики', 'Среднее, медиана и квантиль отвечают на разные вопросы', `
    <p>Мы доказали оптимальность условного среднего для квадрата. Для абсолютной ошибки при E[|Y||x]&lt;∞ и непрерывной условной функции распределения F_x производная E[|Y−c||x] по c равна 2F_x(c)−1. Ноль получается на медиане. При атомах вместо производной используют субградиент, и медиана может быть не единственной.</p>
    ${proof('От модуля к условной медиане', [
      ['∂|y−c|/∂c = 1 при y&lt;c; −1 при y&gt;c', 'Разбираем две линейные ветви модуля. Точка y=c имеет нулевую вероятность при непрерывном распределении.'],
      ['∂E[|Y−c||x]/∂c = P(Y&lt;c|x)−P(Y&gt;c|x)', 'Разностные отношения модуля ограничены по абсолютной величине единицей. Теорема о мажорируемой сходимости разрешает перенести предел под ожидание.'],
      ['P(Y&lt;c|x)−P(Y&gt;c|x)=F_x(c)−(1−F_x(c))=2F_x(c)−1', 'В нуле производной F_x(c)=1/2. Выпуклость абсолютной ошибки доказывает, что это глобальный минимум.']
    ])}
    ${eq('ρ_q(e)=e(q−𝟙[e&lt;0]), &nbsp; e=y−ŷ, &nbsp; q∈(0,1)<br>∂E[ρ_q(Y−c)|x]/∂c = F_x(c)−q', 'При непрерывности оптимум — условная q-квантиль. Знак остатка важен: если взять ŷ−y, формулу нужно изменить.')}
    <p>У квантильной ошибки производная по c равна 1−q при y&lt;c и −q при y&gt;c. Поэтому её ожидание равно (1−q)F_x(c)−q(1−F_x(c))=F_x(c)−q. Производная ограничена, так что тот же перенос предела под ожидание допустим. При атомах условие оптимума записывается F_x(c−)≤q≤F_x(c).</p>
    <p>RMSE=√MSE возвращает ошибку в единицы ответа и при отсутствии дополнительного штрафа имеет тот же минимум. С регуляризацией √MSE+λ‖w‖² и MSE+λ‖w‖² — разные задачи. MAE меньше реагирует на выбросы ответа, но не защищает автоматически от экстремальных признаков.</p>
    <p>Huber loss равна e²/2 при |e|≤δ и δ(|e|−δ/2) иначе: возле нуля квадратична, в хвостах линейна. MAPE нестабильна около нулевого таргета. Метрику выбирают по цене ошибки, а не только по удобству производной.</p>
  `, 'Регуляризация и практика');

  add('linear-validation', 'Проверка на новых данных', 'От доказанного минимума к полезному прогнозу', `
    <p>Оптимизация доказывает минимальность train-loss внутри класса, но не качество на будущих данных. Разделяй train для весов, validation для выбора признаков, λ и stopping rule, test для окончательной проверки. Если многократно выбирать по test, он перестаёт быть независимой оценкой.</p>
    <p>Для временных данных разделение должно соблюдать время. Если строки относятся к одному человеку или устройству, их часто нужно разделять группами. Нормализация, заполнение пропусков и выбор признаков обучаются только внутри train, в том числе внутри каждого CV-фолда.</p>
  `, 'Регуляризация и практика');

  add('linear-risk', 'Что оценивает validation', 'Риск — ожидание по будущим объектам', `
    ${eq('R(f)=E<sub>(U,Y)∼P</sub>[(Y−f(U))²]<br>R̂<sub>val</sub>(f)=(1/m)Σ<sub>i=1</sub><sup>m</sup>(yᵢ−f(uᵢ))²')}
    <p>Для фиксированной модели, независимой от validation, и i.i.d. validation из P с конечным риском E[R̂_val|f]=R(f). Это обоснование оценки. Но после выбора победителя среди многих моделей по этой же выборке результат становится оптимистичным: победил в том числе шум оценки.</p>
    <p>Если будущее распределение меняется, прежнее ожидание относится уже к другому P. Ни теорема Гаусса–Маркова, ни малая норма градиента не дают защиты от такого сдвига.</p>
  `, 'Регуляризация и практика');

  add('linear-diagnostics', 'Остатки и ограничения', 'Что смотреть после обучения', `
    ${table(['Наблюдение','Что проверить'],[
      ['Изгиб на графике e против ŷ','Возможна нелинейная форма условного среднего; проверить преобразования признаков.'],
      ['Разброс остатков растёт','Возможна гетероскедастичность; классические SE могут быть неверными.'],
      ['Ошибки идут сериями во времени','Возможна зависимость наблюдений; проверить временной split и ковариацию.'],
      ['Одна точка сильно меняет веса','Проверить выброс ответа и leverage — необычный вектор признаков.'],
      ['Веса скачут, прогноз почти тот же','Проверить ранг и маленькие сингулярные значения.']
    ],'Диагностика гипотез, а не автоматические диагнозы')}
    ${eq('e=(I−P)ε ⇒ Cov(e|X)=σ²(I−P)<br>Var(eᵢ|X)=σ²(1−Pᵢᵢ)', 'Даже при независимом одинаково распределённом шуме обученные остатки обычно зависимы и имеют разные дисперсии.')}
    <p>Диагональ Pᵢᵢ называется leverage: она зависит от геометрии признаков. Большая leverage позволяет точке притянуть прогноз к себе и получить маленький остаток. Поэтому маленький остаток не доказывает отсутствие влияния. В точном МНК со смещением остатки всегда имеют нулевое среднее — этот факт нельзя использовать как эмпирическое подтверждение E[ε|X]=0.</p>
  `, 'Регуляризация и практика');

  add('linear-causality', 'Пределы интерпретации', 'Коэффициент и причинное воздействие', `
    <p>E[Y|U=x] описывает наблюдаемую связь. E[Y|do(X=x)] — средний ответ при вмешательстве, которое принудительно устанавливает признак. Равенство этих величин требует дополнительных условий и дизайна исследования.</p>
    <p>В формуле пропущенного фактора коэффициент может быть ненулевым даже при a₀=0, если γCov(U,Z)≠0. Например, подготовленность до курса влияет и на время решения заданий, и на итоговый результат. Регрессия по времени смешает эти связи. Значимый коэффициент и высокий R² сами по себе не выделяют причинный эффект.</p>
  `, 'Регуляризация и практика');

  add('linear-practice', 'Проверить понимание', 'Три коротких вывода своими руками', `
    <p>Попробуй ответить до раскрытия решения. Эти упражнения не меняют прогресс и доступны в любой момент.</p>
    <details class="math-exercise"><summary>В выборке все x одинаковы. Почему нельзя назвать единственный наклон?</summary><p>Потому что Sₓₓ=0 и столбец x кратен столбцу единиц. При x=c любые a,b с ac+b=ȳ дают один и тот же оптимальный прогноз. Определён прогноз на train, но не наклон.</p></details>
    <details class="math-exercise"><summary>Шум Лапласа имеет среднее 0 и одинаковую дисперсию. МНК стал смещённым?</summary><p>Нет, если E[ε|X]=0 и X полного столбцового ранга. При независимых ошибках сохраняется BLUE. Изменилось другое: MLE соответствует MAE, а не MSE; точные нормальные t-интервалы без дополнительных аргументов применять нельзя.</p></details>
    <details class="math-exercise"><summary>Сделали два экземпляра каждой строки. Нужно ли вдвое усилить λ в MSE + λ‖w‖²?</summary><p>Нет. MSE и штраф остаются теми же, значит оптимум не меняется. В формулах одновременно удваиваются XᵀX, Xᵀy и nλ. Однако копирование не создаёт независимых данных, поэтому нельзя считать, что неопределённость весов уменьшилась как от новых наблюдений.</p></details>
  `, 'Регуляризация и практика');

  add('linear-sources', 'Источники и маршрут чтения', 'Где продолжить разбор', `
    <p>Это самостоятельный синтез: доказательства изложены в единой системе обозначений, с собственным числовым примером и явными условиями применимости. В источниках могут отличаться знак остатка, буквы a и b, а также множители 1/n и 1/2 — сравнивай целиком функцию потерь.</p>
    <div class="theory-sources"><span>Русскоязычные материалы</span>
    ${Object.entries({habr:'Андрей Хлевнюк — «Основы линейной регрессии»: ковариация и геометрия',linear:'Яндекс Учебник — линейные модели: МНК и регуляризация',probability:'Яндекс Учебник — вероятностный подход: шум и loss',bayes:'Яндекс Учебник — байесовский подход: prior и posterior',statistics:'О. А. Демидова, НИУ ВШЭ — Гаусс–Марков, оценки дисперсии и интервалы (PDF)'}).map(([key,label])=>`<a class="theory-reference" href="${reading[key]}" target="_blank" rel="noreferrer">${label} <span>↗</span></a>`).join('')}
    </div>
  `, 'Регуляризация и практика');

  return {
    route: 'linear', title: 'Линейная<br><span>регрессия.</span>', label: 'алгоритм / математический разбор',
    lead: 'От производных a и b до матричной проекции, случайного шума и доверительных интервалов. Доказываем формулы и разбираем границы их применимости.',
    outline: blocks.map(({id,label,group}) => [id,label,group]),
    content: blocks.map(({id,label,title,body},i) => section(id, `${String(i+1).padStart(2,'0')} / ${label}`, title, body)).join('')
  };
}
